const raw = $input.first().json;
const body = raw.body ?? raw;
const record = body.record ?? body;

const required = ['farm_id', 'owner_id', 'production_type', 'symptoms_text'];
for (const field of required) {
  if (!record[field]) {
    throw new Error('Missing required field: ' + field);
  }
}

const validTypes = ['cattle', 'swine', 'poultry'];
if (!validTypes.includes(record.production_type)) {
  throw new Error('Invalid production_type: ' + record.production_type);
}

return [{
  json: {
    record_id: record.id ?? null,
    farm_id: record.farm_id,
    owner_id: record.owner_id,
    production_type: record.production_type,
    animal_count_affected: record.animal_count_affected ?? null,
    symptoms_text: record.symptoms_text,
    reported_at: record.reported_at ?? new Date().toISOString(),
    reported_by: record.reported_by ?? null
  }
}];

const p = $input.first().json;
const model = $env.DEEPSEEK_MODEL || 'deepseek-chat';

const systemPrompt = 'You are FincApp\'s veterinary AI analyst. IMPORTANT: Respond exclusively in English. Do not use Spanish under any circumstance. Classify health severity and return ONLY valid JSON with all text fields written in English.';

const userPrompt = 'Farm: ' + p.farm_id + '. Type: ' + p.production_type + '. Affected: ' + (p.animal_count_affected || 'unknown') + '. Symptoms: ' + p.symptoms_text + '. Return JSON with: severity (low/medium/high/critical), confidence (0-1), summary, suspected_condition, contagion_risk (bool), immediate_actions (array), notify_veterinarian (bool).';

return [{
  json: {
    ...p,
    llm_model: model,
    prompt_system: systemPrompt,
    prompt_user: userPrompt
  }
}];

const response = $input.first().json;
const upstream = $('Build Severity Prompt').first().json;

if (!response.choices || response.choices.length === 0) {
  throw new Error('LLM returned no choices — check DEEPSEEK_API_KEY env var');
}

let analysis;
try {
  analysis = JSON.parse(response.choices[0].message.content);
} catch (e) {
  throw new Error('LLM response is not valid JSON: ' + response.choices[0].message.content);
}

const required = ['severity', 'summary', 'immediate_actions'];
for (const field of required) {
  if (!(field in analysis)) {
    throw new Error('LLM response missing field: ' + field);
  }
}

const validSeverities = ['low', 'medium', 'high', 'critical'];
if (!validSeverities.includes(analysis.severity)) {
  throw new Error('Invalid severity value: ' + analysis.severity);
}

return [{
  json: {
    record_id: upstream.record_id,
    farm_id: upstream.farm_id,
    owner_id: upstream.owner_id,
    production_type: upstream.production_type,
    symptoms_text: upstream.symptoms_text,
    reported_at: upstream.reported_at,
    severity: analysis.severity,
    confidence: analysis.confidence ?? null,
    summary: analysis.summary,
    suspected_condition: analysis.suspected_condition ?? null,
    contagion_risk: analysis.contagion_risk ?? false,
    immediate_actions: analysis.immediate_actions ?? [],
    notify_veterinarian: analysis.notify_veterinarian ?? false,
    llm_model: response.model,
    analyzed_at: new Date().toISOString()
  }
}];

const p = $input.first().json;
const emoji = p.severity === 'critical' ? '🔴' : '🟠';
const contagion = p.contagion_risk ? 'YES — QUARANTINE IMMEDIATELY' : 'No';
const actionItems = (p.immediate_actions || ['Consult a veterinarian']).map(a => '• ' + a);
const vetNote = p.notify_veterinarian ? ['', '⚕️ Notify veterinarian immediately'] : [];
const parts = [
  emoji + ' *FINCAPP HEALTH ALERT — ' + p.severity.toUpperCase() + '*',
  '',
  'Farm: ' + p.farm_id,
  'Type: ' + p.production_type,
  'Condition: ' + (p.suspected_condition || 'Under assessment'),
  'Contagion risk: ' + contagion
].concat(vetNote).concat([
  '',
  '*Summary:* ' + p.summary,
  '',
  '*Immediate actions:*'
]).concat(actionItems).concat(['', '_Analyzed: ' + p.analyzed_at + '_']);
return [{ json: { ...p, telegram_message: parts.join('\n') } }];
